import json
from pipeline import build,audit,cache,rewrite
from router import route
app=build(route,[audit,cache,rewrite]); results=[]; logs=[]; originals=[]
for path in ["/cached","/v1/cached","/v1/ok","/v1/fail"]:
    req={"path":path}; log=[]
    try: result=app(req,log)
    except ValueError: result="error"
    results.append(result); logs.append(log); originals.append(req["path"])
print(json.dumps({"results":results,"logs":logs,"original_paths":originals}))
```

